namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = "";
    public string Origin { get; set; } = "";
    public string Destination { get; set; } = "";
    public ShipmentStatus Status { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = "";
    public string Description { get; set; } = "";
    public DateTime CreatedAt { get; set; }
    public DateTime LastUpdated { get; set; }
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<ShipmentDto>> GetMyShipmentsAsync();
    Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public ClientShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        var result = await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments");
        return result ?? new();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        var result = await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my");
        return result ?? new();
    }

    public async Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }
}

