@page "/"
@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment</PageTitle>

<div class="container mt-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Enter your tracking number to check shipment status.</p>

    <div class="row mt-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="Search" disabled="@searching">
                    @if (searching)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (searched)
    {
        @if (shipment != null)
        {
            <div class="card mt-4">
                <div class="card-header">
                    <h5 class="mb-0">Tracking: @shipment.TrackingNumber</h5>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <p><strong>Origin:</strong> @shipment.Origin</p>
                            <p><strong>Destination:</strong> @shipment.Destination</p>
                            <p><strong>Description:</strong> @shipment.Description</p>
                        </div>
                        <div class="col-md-6">
                            <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></p>
                            <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</p>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                            }
                        </div>
                    </div>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning mt-4">
                No shipment found with tracking number "@trackingNumber".
            </div>
        }
    }
</div>

@code {
    private string trackingNumber = "";
    private ShipmentDto? shipment;
    private bool searched;
    private bool searching;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

