@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container mt-4">
    <h1>Shipments Dashboard</h1>

    <div class="row mb-3">
        <div class="col-md-3">
            <label class="form-label">Filter by Status</label>
            <select class="form-select" @bind="statusFilter">
                <option value="">All</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
    </div>

    @if (shipments == null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Last Updated</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td>@s.TrackingNumber</td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</td>
                            <td>@s.LastUpdated.ToString("MMM dd, yyyy HH:mm")</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto;"
                                        value="@s.Status"
                                        @onchange="(e) => UpdateStatus(s.Id, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status" selected="@(status == s.Status)">@status</option>
                                    }
                                </select>
